#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
601 张新姿势的命名表（逐张看图人工填写）。

命名规则（与第一批 205 条保持一致）：
  name   = '<体位> · <动作细节>'      中文短名
  desc   = 一句中文说明，描述画面实际动作
  prompt = 英文描述，**这才是真正发给生图模型的内容**

⚠️ 两个铁律（第一批踩过）：
1. **idx 必须与 sheet_index_new.json 核对，不能凭记忆写**。
   上一批凭记忆写 add(45,...) 连续改错两次。这里 add() 内置断言：
   重复 idx 直接抛错，越界也抛错。
2. **不要批量套模板**。曾出现过 8 条中文名完全一样的「批量退化」，
   后来靠加唯一性断言才查出来。所有 add() 必须对应真实画面。

用法（在 09-pose-names-new.py 里写 add(...)）：
  add(0,'站立 · 双手叉腰','双脚分开站立，双手叉腰，肩部打开','standing with feet apart and both hands on the hips, shoulders open')
"""
import re

# idx -> (name, desc, prompt)
_NAMES = []


def add(idx, name, desc, prompt):
    if not (0 <= idx <= 600):
        raise ValueError(f'idx {idx} 越界（有效 0..600）')
    if any(e[0] == idx for e in _NAMES):
        raise ValueError(f'idx {idx} 重复添加')
    for f in (name, desc, prompt):
        if not f or not f.strip():
            raise ValueError(f'idx {idx} 有空字段：{name!r} {desc!r} {prompt!r}')
    if not re.search(r'[a-zA-Z]', prompt):
        raise ValueError(f'idx {idx} 的 prompt 不像英文：{prompt!r}')
    _NAMES.append((idx, name.strip(), desc.strip(), prompt.strip()))


def all_names():
    return sorted(_NAMES, key=lambda x: x[0])


def coverage(total=601):
    got = {e[0] for e in _NAMES}
    missing = [i for i in range(total) if i not in got]
    return len(got), missing


