add(573, '深蹲 · 双肘撑膝低头', '深深下蹲，双膝屈曲到极限，双肘撑在大腿上，头部低垂', 'squatting very deep with both knees fully bent, the elbows braced on the thighs and the head dropped')
add(574, '站立 · 单手抱头侧倾', '身体向侧方倾斜站立，一只手弯肘举到头侧，另一只手按在腹前', 'standing with the body leaning to one side, one arm bent up beside the head and the other hand resting in front of the abdomen')
add(575, '行走 · 俯身前垂双手', '身体向前弯垂，双手朝地面下垂，双腿一前一后迈开', 'hinged forward with both arms hanging down toward the floor, the legs split one in front of the other')
add(576, '平衡 · 后折腿双臂上合', '单腿站立，一条腿向后折起，双臂在头顶斜上方交合，躯干微微后仰', 'balancing on one leg with the other folded back, both arms meeting and closing above the head as the torso leans slightly back')
add(577, '支撑 · 蹲姿双手撑地', '蹲低成半跪式支撑，双手撑在大腿前方的地面上，双臂伸直，背部拱起', 'lowered into a crouching support with both hands planted on the ground in front of the thighs, arms straight and the back arched')
add(578, '俯卧撑 · 平板支撑后踢', '身体斜向悬空成平板俯撑，双臂伸直撑地，双腿向后伸直并抬起', 'held in an angled plank with both arms straight and the legs extended back and lifted off the ground')
add(579, '深蹲 · 深蹲双臂上举交叠', '双脚并拢深深下蹲，双臂向上举过头顶并在前方交叠成环', 'squatting deeply with the feet together, both arms raised overhead and crossed together into an arch')
add(580, '舞蹈 · 双手撑地双腿腾空', '双手撑在地面上，身体腾空旋转，一条腿向上伸直，另一条腿弯曲', 'both hands planted on the ground with the body airborne in a rotation, one leg extended straight up and the other leg bent')
add(581, '弓步 · 大开步双臂平展', '双腿大幅分开成大弓步，双臂向两侧水平平举展开，躯干侧转', 'in a very wide lunge with both arms stretched out horizontally to the sides and the torso turned')
add(582, '坐姿 · 悬空撑地屈腿', '半躺悬空坐姿，双手在身后撑地支撑，双腿屈曲抬起并向一侧偏移', 'reclining in a supported seat with both hands planted behind, both legs bent and lifted, shifted to one side')
add(583, '奔跑 · 屈臂交叉步', '向前奔跑，双腿交叉跨步，双臂屈肘前后快速摆动', 'running forward with the legs crossing mid-stride and both arms bent at the elbows pumping')
add(584, '平衡 · 勾脚提腿双展臂', '单腿站立，另一条腿屈膝向前提起并勾住脚尖，双臂向两侧张开保持平衡', 'balancing on one leg with the other knee drawn up in front and the toes pointed, both arms spread out to the sides for balance')
add(585, '奔跑 · 前伸手臂交跑', '向前奔跑，双腿交叉迈步，一只手臂向前伸出，另一只手臂屈肘在胸前', 'running forward with crossing steps, one arm reaching out ahead and the other bent in front of the chest')
add(586, '俯身 · 双手垂地', '弯腰俯身，双臂松松垂向地面，双膝微屈，头部向下', 'bent forward at the waist with both arms hanging loosely down toward the ground, knees slightly bent and head lowered')
